 $v=ConvertFrom-Json $_ -AsHashtable -Depth 90
 if($r-ceq'behavior76_attempts.jsonl'){$p=@{};foreach($k in @('window_id','n','slot','run_id','kind','status','stage','milliseconds','input_tokens','output_tokens','total_tokens','thinking_tokens','model_version','started_at')){$p[$k]=$v[$k]};$p.events=@($v.events|ForEach-Object {@{type=$_.type;error_code=$_.error_code;safe_reason=$_.safe_reason;http_status=$_.http_status}});$p}
 elseif($r.EndsWith('/run_final_results.jsonl',[StringComparison]::Ordinal)){@{run_id=$v.run_id;result_id=$v.result_id;verdict=$v.verdict}}
 elseif($r.EndsWith('/action_effects.jsonl',[StringComparison]::Ordinal)){@{action_id=$v.action_id;state=$v.state}}
 elseif($r.EndsWith('/behavior76_fixture_stops.jsonl',[StringComparison]::Ordinal)){@{cause=$v.cause;observed_at=$v.observed_at;binding=$v.binding;effects=@($v.effects|ForEach-Object {@{}});native_evidence=$(if($null-ne$v.native_evidence){@{n=$v.native_evidence.n}}else{$null})}}
 else{$v}
})}
