if((Digest $parentPath) -cne '045adc74308ea3faf3024e2b8070cd97aa9ea1470e0bce025354d88b72dfb879' -or (Digest $zipPath) -cne '0a2d985fe63d0854406dea12b476bbda9501e71a98528f459ae1da3213d6b125'){throw 'Parent raw seal pins changed'}
