try{if($zip.Entries.Count -ne $files.Count){throw 'ZIP cardinality'};foreach($e in $zip.Entries){if($seen.ContainsKey($e.FullName) -or -not $byPath.ContainsKey($e.FullName) -or $e.Length -ne $byPath[$e.FullName].bytes){throw 'ZIP file set differs'};$seen[$e.FullName]=$true;$stream=$e.Open();try{$h=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($stream)).ToLowerInvariant()}finally{$stream.Dispose()};if($h -cne $byPath[$e.FullName].sha256){throw 'ZIP bytes differ'}}}finally{$zip.Dispose()}
Save 'native-local-http-v9-independent-raw-inventory-v1.json' @{version='issue76-independent-raw-inventory-v1';files=$files}
