function OpaqueMap([string]$path){
 $map=@{};foreach($line in [IO.File]::ReadLines($path)){if(-not$line.Trim()){continue};$doc=[Text.Json.JsonDocument]::Parse($line);try{$windowID=$doc.RootElement.GetProperty('window_id').GetString();$number=$doc.RootElement.GetProperty('n').GetInt32()}finally{$doc.Dispose()};$key=$windowID+'|'+$number;if($map.ContainsKey($key)){throw 'Opaque ledger duplicate identity'};$map[$key]=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($line))).ToLowerInvariant()};return $map
}
