if($old.Count-ne707-or$new.Count-ne723){throw 'Exact opaque historical row cardinalities differ'}
foreach($key in $old.Keys){if(-not$new.ContainsKey($key)-or$new[$key]-cne$old[$key]){throw 'Prior707 exact opaque UTF8 row bytes changed'}}
