 foreach($s in $case.steps){$o=JSON $s.outcome_path;$indexedSteps++;$row=@{episode_id=$case.episode_id;arm=$case.masked_arm_id;arm_dir=$dir;step_id=$s.step_id;state=$o.state;owner_input_id=$o.owner_input_id;owner_run_id=$o.owner_run_id;native_entry_ids=$o.native_entry_ids;failure_phase=$o.failure_phase;safe_error_category=$o.safe_error_category};$outcomes.Add($row);if($s.step_id -cin @('turn1','turn2')){$ownerRows.Add($row)};foreach($r in $o.automatic_run_ids){$null=$auto.Add($r)}}
